/* About: intention, connection, form. A brand narrative rather than a sales funnel. */
function vSculpture(){return `<svg viewBox="0 0 600 600" role="img" aria-labelledby="v-art-title"><title id="v-art-title">Formas independentes encontram uma estrutura comum</title><defs><pattern id="v-lines" width="18" height="18" patternUnits="userSpaceOnUse"><path d="M0 0V18" stroke="#734b9c" stroke-opacity=".1"/></pattern></defs><circle cx="300" cy="300" r="247" fill="none" stroke="#cbbdd6"/><path d="M55 300H545M300 55V545" stroke="#d8cddd" stroke-dasharray="3 8"/><g class="v-orbit"><circle cx="300" cy="54" r="7" fill="#ee9b56"/></g><g class="v-piece v-piece-one"><path d="M120 130H280V290H120Z" fill="#734b9c"/><path d="M120 130A160 160 0 0 1 280 290H120Z" fill="#b49bc9"/></g><g class="v-piece v-piece-two"><circle cx="375" cy="208" r="78" fill="#ed9e62"/><circle cx="375" cy="208" r="33" fill="#f0e9df"/></g><g class="v-piece v-piece-three"><path d="M125 320H285V480H125Z" fill="url(#v-lines)"/><path d="M125 480L285 320V480Z" fill="#35273e"/></g><g class="v-piece v-piece-four"><path d="M315 320H475V400A80 80 0 0 1 315 400Z" fill="#b69bcf"/><path d="M315 320H475V351H315Z" fill="#734b9c"/></g><circle cx="300" cy="305" r="13" fill="#f6f3ee" stroke="#734b9c"/><path d="M293 305H307M300 298V312" stroke="#734b9c"/></svg>`}
function vAbout(){return `<article class="v-page"><section class="v-hero"><div class="wrap v-hero-grid"><div class="v-hero-copy"><span class="v-eyebrow">Visão da Catalisa</span><h1>Dar forma<br>ao que vem<br><em>depois.</em></h1><p>Acreditamos que boas ideias merecem uma estrutura para ganhar vida. E que construir o próximo produto pode começar por conectar o que já faz sentido.</p><a href="#v-perspectiva" class="text-link">Conheça nossa perspectiva ↓</a></div><div class="v-hero-art">${vSculpture()}<div class="v-art-caption"><span>01 — intenção</span><span>02 — conexão</span><span>03 — forma</span></div></div></div><div class="wrap v-hero-baseline"><span>Uma plataforma. Muitas possibilidades.</span><span>A forma segue a conexão.</span></div></section>
<section id="v-perspectiva" class="wrap v-statement"><span class="v-eyebrow">O ponto de partida</span><h2>Há ideias demais<br>esperando os sistemas<br><em>se entenderem.</em></h2><div class="v-statement-body"><span class="v-statement-glyph" aria-hidden="true">↗</span><div><p>Uma experiência simples para quem usa costuma exigir muitas conexões por trás. Pessoas, dados, decisões, pagamentos, documentos e conversas precisam trabalhar juntos.</p><p>A Catalisa existe para dar estrutura a essa construção. Organizamos capacidades que podem ser conectadas, reutilizadas e combinadas em produtos com uma identidade própria.</p></div></div></section>
<section class="v-principles"><div class="wrap"><div class="v-principles-heading"><span class="v-eyebrow">Nosso jeito de pensar</span><h2>Peças com propósito.<br>Conexões com sentido.</h2><p>Três ideias orientam a plataforma.<br>Explore cada uma.</p></div><div class="v-principles-layout"><div class="v-principle-controls" role="group" aria-label="Princípios da Catalisa"><button data-v-principle="0" aria-pressed="true"><span>01</span> Clareza <b>↗</b></button><button data-v-principle="1" aria-pressed="false"><span>02</span> Composição <b>↗</b></button><button data-v-principle="2" aria-pressed="false"><span>03</span> Responsabilidade <b>↗</b></button></div><div class="v-principle-scene" data-mode="0"><div class="v-principle-shapes" aria-hidden="true"><i></i><i></i><i></i><i></i></div><div class="v-principle-description" aria-live="polite"><h3>Entender antes de conectar.</h3><p>Cada capacidade tem um papel. Saber o que ela faz e onde termina ajuda a construir produtos mais compreensíveis para quem decide, cria e opera.</p></div></div></div></div></section>
<section class="v-evolution wrap"><div><span class="v-eyebrow">Uma base para evoluir</span><h2>O próximo passo<br>não precisa começar<br><em>do zero.</em></h2></div><div class="v-evolution-body"><p>Um produto muda quando o negócio muda. Uma nova jornada, um novo canal, uma regra diferente. A estrutura precisa acompanhar esse movimento.</p><p>Building blocks organizam capacidades. Workflows conectam etapas. Agentes aproximam conversa e ação. Governança estabelece limites e mantém o histórico do que acontece.</p><a class="text-link" href="/arquitetura/">Entenda a arquitetura ↗</a><div class="v-evolution-track" aria-hidden="true"><i></i><span></span><i></i><span></span><i></i></div></div></section>
<section class="v-products"><div class="wrap"><span class="v-eyebrow">A visão encontra o mundo</span><h2>Uma mesma origem.<br>Expressões próprias.</h2><p class="v-products-intro">Banking e Credit tornam essa ideia concreta: experiências diferentes construídas sobre capacidades da plataforma.</p><div class="v-product-pair"><a class="v-product v-product-bank" href="/ecossistema/banking/"><div class="v-product-art" aria-hidden="true"><div class="v-bank-phone"><i></i><span>banking</span><b>↗</b><hr><hr><hr></div><div class="v-bank-orbit"></div></div><span class="v-eyebrow">Banking Platform</span><h3>Uma relação.<br>Muitos pontos de contato.</h3><p>Aplicativo, desktop do titular e console de operação conectam a experiência de quem usa à rotina de quem cuida.</p><span class="text-link">Conheça Banking ↗</span></a><a class="v-product v-product-credit" href="/ecossistema/credit/"><div class="v-product-art" aria-hidden="true"><div class="v-credit-paper"><span>credit</span><i></i><i></i><i></i><b>↗</b></div><div class="v-credit-ring"></div></div><span class="v-eyebrow">Credit Platform</span><h3>Da intenção<br>ao acompanhamento.</h3><p>Produto, política, formalização e operação se conectam para dar continuidade à jornada de crédito.</p><span class="text-link">Conheça Credit ↗</span></a></div></div></section>
<section class="wrap v-human"><span class="v-eyebrow">Tecnologia a serviço de uma intenção</span><h2>Construir é conectar.<br><em>O sentido vem das pessoas.</em></h2><div><p>A tecnologia amplia o que podemos fazer. As pessoas definem por que fazer, o que importa e quando é preciso olhar de novo.</p><p>Por isso, autonomia e responsabilidade fazem parte da mesma conversa na Catalisa: permissões, evidências e espaço para a decisão humana.</p></div><a class="text-link" href="/governanca/">Como pensamos a governança ↗</a></section>
<section class="v-ending"><div class="wrap"><span class="v-eyebrow">O que você quer colocar no mundo?</span><h2>A próxima forma<br>começa com <em>uma ideia.</em></h2><div><a class="v-button" href="/lab/">Imagine seu produto ↗</a><a class="text-link" href="/contato/">Converse com a Catalisa ↗</a></div><span class="v-ending-circle" aria-hidden="true"></span></div></section></article>`}
const vPriorPage=cPage;cPage=function(route,blocks){return route==='/visao/'?vAbout():vPriorPage(route,blocks)};
if(typeof document!=='undefined')document.addEventListener('DOMContentLoaded',()=>{const content=[['Entender antes de conectar.','Cada capacidade tem um papel. Saber o que ela faz e onde termina ajuda a construir produtos mais compreensíveis para quem decide, cria e opera.'],['Combinar para criar o próprio.','Capacidades compartilhadas não precisam gerar produtos iguais. A combinação, a jornada e a experiência dão forma ao contexto de cada negócio.'],['Autonomia com limites claros.','Permissões, histórico e revisão humana ajudam a definir quem pode agir, acompanhar o que aconteceu e cuidar das decisões que importam.']];document.querySelectorAll('[data-v-principle]').forEach(b=>b.addEventListener('click',()=>{const i=Number(b.dataset.vPrinciple);document.querySelectorAll('[data-v-principle]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelector('.v-principle-scene').dataset.mode=i;document.querySelector('.v-principle-description h3').textContent=content[i][0];document.querySelector('.v-principle-description p').textContent=content[i][1]}))});
